<?php declare(strict_types=1);namespace StudPulse\Bars;use StudPulse\Http\ApiError;use StudPulse\Integrations\{HttpClient,MpeiSchedule};final class BarsTeacherDirectory{public const URL='https://bars.mpei.ru/bars_web/Open/EmployeeSchedule/_PartialSchedule';public static function search(string$query,string$by,?string$group):array{$filters=['ViewType'=>'1','SortOrder'=>'Employee.FIO','Page'=>'1','PageSize'=>'100','FilterFIO'=>$by==='name'?$query:'','FilterDiscipline'=>$by==='subject'?$query:'','FilterEmployeeScheduleType'=>['Value'=>'1;2;3;4;'],];try{$response=HttpClient::request('GET',self::URL.'?'.http_build_query(['query'=>json_encode($filters,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),],'','&',PHP_QUERY_RFC3986),['Accept: text/html','X-Requested-With: XMLHttpRequest','User-Agent: StudPulse/1.0']);}catch(ApiError){throw new ApiError(502,'BARS_TEACHERS_UNAVAILABLE','БАРС сейчас не ответил на поиск преподавателей.');}return self::entries($response['raw'],$group);}public static function entries(string$html,?string$group):array{$page=BarsHtml::document($html);if(!$page->query('//*[@id="tbl__PartialSchedule"]')->length){throw new ApiError(502,'BARS_TEACHERS_FORMAT','БАРС вернул справочник преподавателей в неизвестном формате.');}$groupKey=$group?MpeiSchedule::groupKey($group):'';$contacts=[];foreach($page->query('//*[@id="tbl__PartialSchedule"]//tbody/tr')as$row){$cells=$page->query('./td',$row);if($cells->length<4)continue;$address=$page->query('.//a[starts-with(@href,"mailto:")]',$cells[0])->item(0);if(!$address instanceof \DOMElement)continue;$email=strtolower(substr($address->getAttribute('href'),7));if(!str_ends_with($email,'@mpei.ru')||!filter_var($email,FILTER_VALIDATE_EMAIL))continue;$name=BarsHtml::text($cells[0]);$name=trim(str_ireplace($email,'',$name));$subject=BarsHtml::text($cells[2]);if($name==='')continue;$groups=explode(';',preg_replace('/\([^()]*\)/u','',BarsHtml::text($cells[3]))??'');$own=$groupKey!==''&&in_array($groupKey,array_map(MpeiSchedule::groupKey(...),$groups),true);$contacts[$email]??=['name'=>mb_substr($name,0,180),'email'=>$email,'subjects'=>[],'ownGroup'=>false];if($subject!=='')$contacts[$email]['subjects'][mb_substr($subject,0,180)]=true;$contacts[$email]['ownGroup']=$contacts[$email]['ownGroup']||$own;}usort($contacts,static fn(array$a,array$b):int=>$b['ownGroup']<=>$a['ownGroup']?:strcmp($a['name'],$b['name']));return array_map(static function(array$item):array{$item['subjects']=array_slice(array_keys($item['subjects']),0,6);return$item;},array_slice($contacts,0,18));}}